const order = $input.first().json.body;

// Валидация
if (!order.customerId) {
  throw new Error('customerId обязателен');
}
if (!order.items || order.items.length === 0) {
  throw new Error('items не может быть пустым');
}

// Создаем задачу
const task = {
  taskId: 'task_' + Date.now(),
  orderId: 'ord_' + Date.now(),
  customerId: order.customerId,
  customerEmail: order.customerEmail || null,
  items: order.items,
  total: order.total,
  status: 'created',
  createdAt: new Date().toISOString(),
  retryCount: 0,
  maxRetries: 3
};

console.log('📦 Создан заказ:', task.orderId);
console.log('💰 Сумма:', task.total);

// Возвращаем данные с orderId и taskId
return [{
  json: {
    orderId: task.orderId,
    taskId: task.taskId,
    task: task,
    message: '✅ Заказ принят в обработку',
    status: 'queued'
  }
}];

// ============================================
// ОБРАБОТКА ОТВЕТА ОТ EVENT STORE
// ============================================

const eventStoreResponse = $input.first().json;

console.log('📥 Ответ от Event Store:', eventStoreResponse);

// Возвращаем то, что пришло на вход (данные не меняются)
return [$input.first().json];

const input = $input.first().json;

// Пытаемся найти orderId в разных местах
const orderId = input.orderId || 
                input.data?.orderId || 
                input.task?.orderId || 
                'ord_' + Date.now();

const taskId = input.taskId || 
               input.data?.taskId || 
               input.task?.taskId || 
               'task_' + Date.now();

const response = {
  orderId: orderId,
  taskId: taskId,
  message: "✅ Заказ принят в обработку",
  status: "queued",
  estimatedTime: "30 секунд"
};

console.log('📤 Ответ:', response);

return [{
  json: response
}];
